#include <iostream>
#include <algorithm>
using namespace std;

long long compute_gcd(long long a, long long b) {
    while (b != 0) {
        long long temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

struct Fraction {
    long long num, den;
    Fraction() : num(0), den(1) {}
    Fraction(long long n, long long d) : num(n), den(d) {}
    void simplify() {
        long long g = compute_gcd(num, den);
        num /= g;
        den /= g;
    }
    bool less_than(const Fraction& other) const {
        return num * other.den < other.num * den;
    }
    void display() const {
        cout << num << "/" << den;
    }
};

int main() {
    long long a, b, count;
    cin >> a >> b >> count;
    Fraction limit(50, 1);
    Fraction base(a, b);
    long long min_r = 0, min_i = 1;
    for (long long i = 1; i <= count; ++i) {
        long long r = (base.num * i) / base.den;
        long long z = (base.num * i) % base.den;
        if (z > base.den / 2) {
            r++;
            z = base.den - z;
        }
        Fraction current(z, i * base.den);
        if (current.less_than(limit)) {
            limit = current;
            min_r = r;
            min_i = i;
        }
    }
    cout << min_r;
}
